B.TENANT_REF_ID = #{tenantRefId}
AND B.MEMBER_REF_ID = #{memberRefId}
AND B.APP_REF_ID = #{appRefId}
AND B.STATUS = 'ACTIVE' AND B.IS_DELETE = 0
AND P.PERMISSION_CODE = #{permissionCode}

mapper.select:
SELECT B.ID AS bindingRefId, B.ROLE_REF_ID AS roleRefId, RP.PERMISSION_REF_ID AS permissionRefId, F.FIELD_CODE AS fieldCode, F.MASK_STRATEGY AS maskStrategy, FP.READ_EFFECT AS readEffect, FP.WRITE_EFFECT AS writeEffect
INNER JOIN PEACH_ROLE_FIELD_POLICY FP ON FP.ROLE_REF_ID = B.ROLE_REF_ID AND FP.PERMISSION_REF_ID = RP.PERMISSION_REF_ID AND FP.TENANT_REF_ID = B.TENANT_REF_ID AND FP.APP_REF_ID = B.APP_REF_ID AND FP.STATUS = 'ACTIVE' AND FP.IS_DELETE = 0 INNER JOIN PEACH_FIELD_DEFINITION F ON F.ID = FP.FIELD_REF_ID AND F.RESOURCE_CODE = #{resourceCode} AND F.STATUS = 'ACTIVE' AND F.IS_DELETE = 0 AND (F.APP_REF_ID IS NULL OR F.APP_REF_ID = B.APP_REF_ID) AND ((F.OWNER_TYPE = 'SYSTEM' AND F.TENANT_REF_ID IS NULL) OR (F.OWNER_TYPE = 'TENANT' AND F.TENANT_REF_ID = B.TENANT_REF_ID)) WHERE AND B.ID IN
#{bindingRefId}
